    pub(crate) fn worktrees_for(&self, repo: &RepoId) -> &[WorktreeEntry] {
        self.worktrees_by_repo
            .get(repo)
            .map(Vec::as_slice)
            .unwrap_or(&[])
    }

    pub(crate) fn worktree_is_dragging(&self, worktree: &WorktreeId) -> bool {
        self.worktree_dragging.as_ref() == Some(worktree)
    }

    fn reorder_dragged_worktree_over(&mut self, target: &WorktreeId) -> bool {
        let Some(source) = self.worktree_dragging.as_ref() else {
            return false;
        };
        if source == target {
            return false;
        }
        let Some((repo_id, source_index, target_index)) =
            self.worktrees_by_repo
                .iter()
                .find_map(|(repo_id, entries)| {
                    let source_index = entries
                        .iter()
                        .position(|entry| worktree_id_for(&entry.path) == *source)?;
                    let target_index = entries
                        .iter()
                        .position(|entry| worktree_id_for(&entry.path) == *target)?;
                    Some((repo_id.clone(), source_index, target_index))
                })
        else {
            return false;
        };
        let entries = self
            .worktrees_by_repo
            .get_mut(&repo_id)
            .expect("the matching repository was just found");
        let moved = entries.remove(source_index);
        entries.insert(target_index.min(entries.len()), moved);
        true
    }

    pub(crate) fn worktree_is_visible(&self, entry: &WorktreeEntry) -> bool {
        let id = worktree_id_for(&entry.path);
        let hidden_by_general_setting = self.ui_settings.hide_default_branch && entry.is_main
            || self.ui_settings.hide_detached_head && entry.branch.is_none()
            || self.ui_settings.hide_sleeping && self.worktree_is_sleeping(&id);
        if hidden_by_general_setting {
            return false;
        }
        let Some(repo_id) = self
            .worktrees_by_repo
            .iter()
            .find_map(|(repo_id, entries)| {
                entries
                    .iter()
                    .any(|candidate| candidate.path == entry.path)
                    .then_some(repo_id)
            })
        else {
            return true;
        };
        if !self.is_external_worktree(repo_id, entry) {
            return true;
        }
        if self
            .ui_settings
            .repo_imported_external_worktree_paths
            .get(&repo_id.0)
            .is_some_and(|paths| {
                paths
                    .iter()
                    .any(|path| Path::new(path) == entry.path.as_path())
            })
        {
            return true;
        }
        self.ui_settings
            .repo_external_worktree_visibility
            .get(&repo_id.0)
            .is_none_or(|visibility| visibility == "show")
    }

    fn is_external_worktree(&self, repo: &RepoId, entry: &WorktreeEntry) -> bool {
        if entry.is_main
            || self
                .repo_by_id(repo)
                .is_some_and(|record| record.path == entry.path)
        {
            return false;
        }
        let id = worktree_id_for(&entry.path);
        self.worktree_meta
            .get(&id)
            .is_none_or(|meta| meta.created_at_unix_ms == 0)
    }

    pub(crate) fn external_worktree_inbox(&self, repo: &RepoId) -> Vec<&WorktreeEntry> {
        if self
            .ui_settings
            .repo_external_worktree_discovery_suppressed_at
            .contains_key(&repo.0)
            || self
                .ui_settings
                .repo_external_worktree_visibility
                .get(&repo.0)
                .is_none_or(|visibility| visibility != "hide")
        {
            return Vec::new();
        }
        let baseline = self
            .ui_settings
            .repo_external_worktree_inbox_baseline_paths
            .get(&repo.0);
        let imported = self
            .ui_settings
            .repo_imported_external_worktree_paths
            .get(&repo.0);
        self.worktrees_for(repo)
            .iter()
            .filter(|entry| self.is_external_worktree(repo, entry))
            .filter(|entry| {
                let is_listed = |paths: Option<&Vec<String>>| {
                    paths.is_some_and(|paths| {
                        paths
                            .iter()
                            .any(|path| Path::new(path) == entry.path.as_path())
                    })
                };
                !is_listed(baseline) && !is_listed(imported)
            })
            .collect()
    }

