    /// 이 repo의 현재 피커 선택. 엔트리가 없으면 로그인 셸(기본).
    pub(crate) fn worktree_agent_selection(&self, repo: &RepoId) -> AgentChoice {
        self.worktree_agent_draft
            .get(repo)
            .copied()
            .unwrap_or_else(|| match self.ui_settings.default_agent.as_str() {
                "blank" => AgentChoice::LOGIN_SHELL,
                "auto" => self
                    .installed_agents
                    .iter()
                    .copied()
                    .find(|id| {
                        !self
                            .ui_settings
                            .disabled_agents
                            .iter()
                            .any(|disabled| disabled == id)
                    })
                    .map(|id| AgentChoice(Some(id)))
                    .unwrap_or(AgentChoice::LOGIN_SHELL),
                selected => self
                    .installed_agents
                    .iter()
                    .copied()
                    .find(|id| {
                        *id == selected
                            && !self
                                .ui_settings
                                .disabled_agents
                                .iter()
                                .any(|disabled| disabled == id)
                    })
                    .map(|id| AgentChoice(Some(id)))
                    .unwrap_or(AgentChoice::LOGIN_SHELL),
            })
    }

