    /// **디스크 → `from_load` → `begin_layout_restore`의 이음매.** 위의 복원
    /// 테스트들은 `pending_restore_tree`를 직접 세우므로, 저장된 트리를 부팅이
    /// 실제로 **읽어오는지**는 검사하지 못한다 — 그 한 줄이 죽어도 전부 통과한다
    /// (mutation으로 확인했다).
    #[test]
    fn a_saved_layout_is_read_off_disk_and_starts_its_sessions() {
        let mut disk = PersistedState {
            repos: vec![some_repo("booted")],
            worktrees: vec![
                Worktree {
                    id: wt("/tmp/wt-a"),
                    repo_id: RepoId("/tmp/booted".into()),
                    path: PathBuf::from("/tmp/wt-a"),
                    branch: "a".into(),
                    display_name: "a".into(),
                    created_with_agent: None,
                    created_at_unix_ms: 1,
                    linked_github_pr: None,
                    linked_linear_issue: None,
                    linked_linear_issue_workspace_id: None,
                    linked_linear_issue_organization_url_key: None,
                    linked_jira_issue: None,
                    linked_jira_site: None,
                },
                Worktree {
                    id: wt("/tmp/wt-b"),
                    repo_id: RepoId("/tmp/booted".into()),
                    path: PathBuf::from("/tmp/wt-b"),
                    branch: "b".into(),
                    display_name: "b".into(),
                    created_with_agent: None,
                    created_at_unix_ms: 2,
                    linked_github_pr: None,
                    linked_linear_issue: None,
                    linked_linear_issue_workspace_id: None,
                    linked_linear_issue_organization_url_key: None,
                    linked_jira_issue: None,
                    linked_jira_site: None,
                },
            ],
            ..Default::default()
        };
        disk.session.panes = Some(split(
            PersistedAxis::Horizontal,
            0.4,
            leaf("/tmp/wt-a"),
            leaf("/tmp/wt-b"),
        ));

        let mut state = AppState::from_load(LoadDiagnostics {
            state: disk,
            origin: LoadOrigin::Fresh,
            save_blocked: false,
        });
        state.hydration = Hydration::new([]);
        let _ = state.begin_layout_restore();

        let mut pending: Vec<WorktreeId> = state
            .restore
            .as_ref()
            .expect("the saved tree must have started a restore")
            .pending
            .keys()
            .cloned()
            .collect();
        pending.sort_by(|a, b| a.0.cmp(&b.0));
        assert_eq!(
            pending,
            vec![wt("/tmp/wt-a"), wt("/tmp/wt-b")],
            "booting must read the saved tree off disk and start a session for each leaf \
             — if the layout field is never read, there is nothing to restore and the \
             workbench comes up empty every time"
        );

        deliver_start(&mut state, "/tmp/wt-a", true);
        deliver_start(&mut state, "/tmp/wt-b", true);
        assert_eq!(
            restored_shape(&state),
            "(H0.400 wt-a wt-b)",
            "and the tree that comes back must be the one that was on disk"
        );
    }

    /// 복원된 활성 worktree의 pane이 포커스를 받는다.
    #[test]
    fn the_restored_active_worktree_gets_the_focus() {
        let tree = split(
            PersistedAxis::Vertical,
            0.25,
            leaf("/tmp/wt-a"),
            leaf("/tmp/wt-b"),
        );
        let mut state = restoring_state(tree, &["/tmp/wt-a", "/tmp/wt-b"]);
        state.selected_worktree = Some(wt("/tmp/wt-b"));

        deliver_start(&mut state, "/tmp/wt-a", true);
        deliver_start(&mut state, "/tmp/wt-b", true);

        let focused = state
            .focused_session()
            .and_then(|id| state.session_worktrees.get(&id))
            .cloned();
        assert_eq!(
            focused,
            Some(wt("/tmp/wt-b")),
            "focus must land on the worktree that was active when the app closed, not \
             simply on the first pane"
        );
    }

    /// 포커스 변경이 활성 worktree를 따라가는지. 이것이 없으면 플랜의 "포커스
    /// 변경 시 저장" 트리거가 아무것도 바꾸지 않는 공회전이 된다.
    #[test]
    fn focusing_a_pane_makes_its_worktree_the_active_one() {
        let (mut state, _repo, [(_id_a, wt_a), (id_b, wt_b)]) = state_with_two_open_sessions();
        state.selected_worktree = Some(wt_a.clone());

        let pane_b = *state
            .panes()
            .expect("two panes")
            .iter()
            .find(|(_, id)| **id == id_b)
            .map(|(pane, _)| pane)
            .expect("session b has a pane");
        let _ = state.update(Message::PaneClicked(pane_b));

        assert_eq!(
            state.selected_worktree(),
            Some(&wt_b),
            "the focused pane IS the active worktree — otherwise nothing that gets saved \
             ever changes on focus and the save trigger is a no-op"
        );
    }

    // ================= Plan 5 Task 3: 배지 =================

    fn hook(worktree: &str, nonce: u64, name: HookEventName) -> HookEvent {
        HookEvent {
            pane_key: PaneKey(wt(worktree)),
            spawn_nonce: SpawnNonce(nonce),
            claude_session_id: "sid".into(),
            event: name,
            tool_name: None,
            agent_id: None,
            prompt: None,
            background_work_active: Some(false),
            session_crons_active: Some(false),
            interrupted: false,
        }
    }

    /// 배지 장부가 있는 상태. 세션까지 띄우지 않고 장부만 세운다 — 배지 규칙은
    /// 세션 객체와 무관하다.
    fn state_with_badge(worktree: &str, nonce: u64) -> AppState {
        let mut state = AppState::default();
        state
            .badges
            .insert(wt(worktree), PaneBadge::new(SpawnNonce(nonce)));
        state
    }

    /// **세션 교체 창을 막는 유일한 방어.** `PaneKey`는 worktree에서 파생돼 세션이
    /// 바뀌어도 같으므로, 옛 프로세스의 늦은 훅(async라 더 늦다)이 새 세션의 배지를
    /// 덮을 수 있다.
    #[test]
    fn a_hook_carrying_a_stale_nonce_is_dropped() {
        let mut state = state_with_badge("/tmp/wt-a", 5);
        // 현 세대의 이벤트가 배지를 waiting으로 만든다.
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            5,
            HookEventName::PermissionRequest,
        )));
        assert_eq!(
            state.badges[&wt("/tmp/wt-a")].hook.map(|(s, _)| s),
            Some(HookState::Waiting),
            "precondition: the current generation's hook was accepted"
        );

        // 옛 세대(nonce 4)의 늦은 `Stop`이 도착한다.
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            4,
            HookEventName::Stop,
        )));
        assert_eq!(
            state.badges[&wt("/tmp/wt-a")].hook.map(|(s, _)| s),
            Some(HookState::Waiting),
            "a hook from a previous spawn must not overwrite the live badge — the old \
             process's Stop would otherwise mark the NEW session finished"
        );

        // 대조군: 같은 `Stop`이 현 세대로 오면 반영된다. 이게 없으면 위 단언이
        // "Stop이 아예 처리되지 않는다"로도 설명된다.
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            5,
            HookEventName::Stop,
        )));
        assert_eq!(
            state.badges[&wt("/tmp/wt-a")].hook.map(|(s, _)| s),
            Some(HookState::Done),
            "control: the same event at the current nonce IS applied"
        );
    }

    #[test]
    fn a_confirmed_daemon_reattach_binds_its_original_nonce_once() {
        let worktree = wt("/tmp/wt-a");
        let mut state = state_with_badge("/tmp/wt-a", 9);
        state
            .badges
            .get_mut(&worktree)
            .unwrap()
            .allow_reattach_nonce_bind = true;

        assert!(state.apply_hook(&hook("/tmp/wt-a", 3, HookEventName::UserPromptSubmit,)));
        let rebound = &state.badges[&worktree];
        assert_eq!(rebound.expected, SpawnNonce(3));
        assert!(!rebound.allow_reattach_nonce_bind);
        assert_eq!(
            rebound.hook.map(|(value, _)| value),
            Some(HookState::Working)
        );

        assert!(
            !state.apply_hook(&hook("/tmp/wt-a", 2, HookEventName::Stop)),
            "after the one-time daemon rebind, another stale generation must be rejected"
        );
        assert_eq!(
            state.badges[&worktree].hook.map(|(value, _)| value),
            Some(HookState::Working)
        );
    }

    #[test]
    fn a_hook_for_a_pane_we_never_spawned_is_dropped() {
        let mut state = state_with_badge("/tmp/wt-a", 1);
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/other",
            1,
            HookEventName::PermissionRequest,
        )));
        assert!(
            state.badges[&wt("/tmp/wt-a")].hook.is_none(),
            "an event for an unknown pane must not touch any other pane's badge"
        );
        assert!(!state.badges.contains_key(&wt("/tmp/other")));
    }

    #[test]
    fn enter_and_escape_clear_only_a_fresh_claude_question_wait() {
        use suaegi_term::input_types::{KeyLocation, Mods};

        for key in [NamedKey::Enter, NamedKey::Escape] {
            let (mut state, id, worktree, _pane) = state_with_one_open_session();
            state
                .badges
                .insert(worktree.clone(), PaneBadge::new(SpawnNonce(7)));
            let mut question = hook(&worktree.0, 7, HookEventName::PreToolUse);
            question.tool_name = Some("AskUserQuestion".into());
            assert!(state.apply_hook(&question));
            assert!(state.badges[&worktree].waiting_for_question);

            assert!(state.infer_claude_question_resolved(
                id,
                &KeyInput {
                    key: TermKey::Named(key),
                    physical_latin: None,
                    location: KeyLocation::Standard,
                    mods: Mods::default(),
                    text: None,
                    repeat: false,
                }
            ));
            assert_eq!(
                state.badges[&worktree].hook.map(|(state, _)| state),
                Some(HookState::Working)
            );
            assert!(!state.badges[&worktree].waiting_for_question);
        }

        let (mut permission, id, worktree, _pane) = state_with_one_open_session();
        permission
            .badges
            .insert(worktree.clone(), PaneBadge::new(SpawnNonce(8)));
        let mut bash = hook(&worktree.0, 8, HookEventName::PermissionRequest);
        bash.tool_name = Some("Bash".into());
        assert!(permission.apply_hook(&bash));
        assert!(!permission.infer_claude_question_resolved(
            id,
            &KeyInput {
                key: TermKey::Named(NamedKey::Escape),
                physical_latin: None,
                location: KeyLocation::Standard,
                mods: Mods::default(),
                text: None,
                repeat: false,
            }
        ));
        assert_eq!(
            permission.badges[&worktree].hook.map(|(state, _)| state),
            Some(HookState::Waiting),
            "Escape must not clear an ordinary permission request"
        );
    }

    /// `SessionStart`는 장부를 **지운다**. 옛 세션의 `Working`을 물려받으면 아무
    /// 일도 안 하는 pane이 도는 스피너로 보인다.
    #[test]
    fn session_start_clears_a_stale_hook_state() {
        let mut state = state_with_badge("/tmp/wt-a", 1);
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::PreToolUse,
        )));
        assert!(
            state.badges[&wt("/tmp/wt-a")].hook.is_some(),
            "precondition"
        );

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::SessionStart,
        )));
        assert!(
            state.badges[&wt("/tmp/wt-a")].hook.is_none(),
            "a fresh session starts from Unknown, not from whatever the last one was doing"
        );
    }

    #[test]
    fn turn_boundaries_preserve_live_background_and_cron_evidence_until_drained_or_interrupted() {
        let id = wt("/tmp/wt-a");
        let mut state = state_with_badge(&id.0, 1);

        let mut running = hook(&id.0, 1, HookEventName::Stop);
        running.background_work_active = Some(true);
        running.session_crons_active = Some(true);
        assert!(state.apply_hook(&running));
        assert_eq!(
            state.badges[&id].hook.map(|(state, _)| state),
            Some(HookState::Working)
        );

        let mut thin_failure = hook(&id.0, 1, HookEventName::StopFailure);
        thin_failure.background_work_active = None;
        thin_failure.session_crons_active = None;
        assert!(state.apply_hook(&thin_failure));
        assert_eq!(
            state.badges[&id].hook.map(|(state, _)| state),
            Some(HookState::Working),
            "a thin non-interrupted StopFailure cannot discard prior live work"
        );

        let mut drained = hook(&id.0, 1, HookEventName::Stop);
        drained.background_work_active = Some(false);
        drained.session_crons_active = None;
        assert!(state.apply_hook(&drained));
        assert_eq!(
            state.badges[&id].hook.map(|(state, _)| state),
            Some(HookState::Done),
            "a present drained task inventory also clears an omitted empty cron inventory"
        );

        let mut scheduled = hook(&id.0, 1, HookEventName::Stop);
        scheduled.background_work_active = Some(false);
        scheduled.session_crons_active = Some(true);
        assert!(state.apply_hook(&scheduled));
        assert_eq!(
            state.badges[&id].hook.map(|(state, _)| state),
            Some(HookState::Working)
        );

        let mut interrupted = hook(&id.0, 1, HookEventName::StopFailure);
        interrupted.background_work_active = None;
        interrupted.session_crons_active = None;
        interrupted.interrupted = true;
        assert!(state.apply_hook(&interrupted));
        assert_eq!(
            state.badges[&id].hook.map(|(state, _)| state),
            Some(HookState::Done)
        );
        assert!(!state.badges[&id].claude_background_work_active);
        assert!(!state.badges[&id].claude_session_crons_active);
    }

    #[test]
    fn prompt_cache_timer_tracks_claude_completion_and_clears_on_resume_reset_and_disable() {
        let id = wt("/tmp/wt-a");
        let mut state = state_with_badge("/tmp/wt-a", 1);
        state.ui_settings.prompt_cache_timer_enabled = true;
        state.ui_settings.prompt_cache_ttl_minutes = 5;

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::PreToolUse,
        )));
        assert_eq!(
            state.prompt_cache_remaining_seconds(&id),
            None,
            "working starts a request, but the reusable prompt cache window begins only when it finishes"
        );

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::Stop,
        )));
        assert!(matches!(
            state.prompt_cache_remaining_seconds(&id),
            Some(1..=300)
        ));

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::PreToolUse,
        )));
        assert_eq!(
            state.prompt_cache_remaining_seconds(&id),
            None,
            "resuming work consumes the previous completion window"
        );

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::Stop,
        )));
        assert!(state.prompt_cache_remaining_seconds(&id).is_some());
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::SessionStart,
        )));
        assert_eq!(
            state.prompt_cache_remaining_seconds(&id),
            None,
            "a new Claude session cannot inherit the old session's cache timer"
        );

        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::PreToolUse,
        )));
        let _ = state.update(Message::HookArrived(hook(
            "/tmp/wt-a",
            1,
            HookEventName::Stop,
        )));
        let _ = state.update(Message::UiSettingToggled(
            UiSetting::PromptCacheTimerEnabled,
        ));
        assert!(state.prompt_cache_started.is_empty());
        assert_eq!(state.prompt_cache_remaining_seconds(&id), None);
    }

